#!/usr/bin/env python3
"""Validates model-catalog/ against the schema and rules documented in
CONVENTIONS.md — read that file in full before adding a new entry.

Checks, per entry (entries/*.yaml AND archived/*.yaml):
  - required fields present: model_name, engine, served_name, port, status
  - port is an int
  - status matches the directory the file lives in (entries/ -> active,
    archived/ -> archived)

Catalog-wide checks:
  - served_name is unique across EVERY .yaml file in model-catalog/,
    including archived/ — this is the load-bearing rule from
    CONVENTIONS.md ("The non-obvious rule"). A served_name reused by an
    archived entry is exactly as much a conflict as one reused by another
    active entry.

Stdlib-only except for PyYAML (yaml), which is already a dependency
elsewhere in this repo's toolchain (same convention as
chrisjohnson/local-ai-machine's own catalog/ tooling) — falls back to a
minimal hand-rolled parser if PyYAML isn't installed, since this script
may run inside an agent's own scratch workspace where pip installs aren't
guaranteed available.

Usage:
    python3 validate_catalog.py [--root DIR] [--json]

Exit code: 0 if the catalog is valid, 1 otherwise.
"""
from __future__ import annotations

import argparse
import json as jsonlib
import sys
from pathlib import Path
from typing import Optional

try:
    import yaml  # type: ignore
    HAVE_YAML = True
except ImportError:
    HAVE_YAML = False


REQUIRED_FIELDS = ["model_name", "engine", "served_name", "port", "status"]
DIR_TO_STATUS = {"entries": "active", "archived": "archived"}


def _minimal_yaml_parse(text: str) -> dict:
    """Tiny fallback parser for this catalog's deliberately flat
    `key: value` schema only — not a general YAML parser. Used only when
    PyYAML isn't importable in the calling environment."""
    result: dict = {}
    for line in text.splitlines():
        line = line.split("#", 1)[0].strip()
        if not line or ":" not in line:
            continue
        key, _, value = line.partition(":")
        key = key.strip()
        value = value.strip().strip('"').strip("'")
        if value.lstrip("-").isdigit():
            result[key] = int(value)
        else:
            result[key] = value
    return result


def load_entry(path: Path) -> dict:
    text = path.read_text()
    if HAVE_YAML:
        data = yaml.safe_load(text)
        if not isinstance(data, dict):
            raise ValueError(f"{path}: did not parse to a mapping")
        return data
    return _minimal_yaml_parse(text)


def find_entry_files(root: Path):
    for sub in ("entries", "archived"):
        d = root / sub
        if not d.exists():
            continue
        for f in sorted(d.glob("*.yaml")):
            yield sub, f


def validate(root: Path) -> tuple[bool, list]:
    problems: list[str] = []
    served_name_owners: dict = {}  # served_name -> list of relative paths

    any_files = False
    for sub, path in find_entry_files(root):
        any_files = True
        rel = path.relative_to(root)
        try:
            entry = load_entry(path)
        except Exception as e:  # noqa: BLE001
            problems.append(f"{rel}: failed to parse ({e})")
            continue

        for field in REQUIRED_FIELDS:
            if field not in entry or entry[field] in (None, ""):
                problems.append(f"{rel}: missing required field '{field}'")

        if "port" in entry and not isinstance(entry["port"], int):
            problems.append(f"{rel}: 'port' must be an integer, got {entry['port']!r}")

        expected_status = DIR_TO_STATUS[sub]
        if entry.get("status") not in (None, "") and entry.get("status") != expected_status:
            problems.append(
                f"{rel}: status={entry.get('status')!r} does not match its "
                f"directory ({sub!r} implies status: {expected_status!r})"
            )

        served_name = entry.get("served_name")
        if served_name:
            served_name_owners.setdefault(served_name, []).append(str(rel))

    if not any_files:
        problems.append("no entry files found under entries/ or archived/ — nothing to validate")

    for served_name, owners in served_name_owners.items():
        if len(owners) > 1:
            problems.append(
                f"served_name {served_name!r} is used by more than one file, "
                f"including across entries/ and archived/: {owners} — "
                f"CONVENTIONS.md requires served_name to be unique across "
                f"ALL files in model-catalog/, not just within one directory"
            )

    return (len(problems) == 0), problems


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--root", default=None, help="model-catalog/ directory (default: this script's own directory)")
    ap.add_argument("--json", action="store_true")
    args = ap.parse_args()

    root = Path(args.root) if args.root else Path(__file__).resolve().parent
    ok, problems = validate(root)

    if args.json:
        print(jsonlib.dumps({"valid": ok, "problems": problems}, indent=2))
    else:
        if ok:
            print("model-catalog: VALID — no problems found.")
        else:
            print("model-catalog: INVALID")
            for p in problems:
                print(f"  - {p}")

    sys.exit(0 if ok else 1)


if __name__ == "__main__":
    main()
